// ══ S — Single Responsibility: split a God Object ══════════════
// BEFORE — one class, four concerns, four reasons to change
class UserServiceBad {
  save(user)    { /* write to DB */ }
  sendEmail(u)  { /* call SMTP — unrelated to persistence */ }
  toCsv(users)  { return users.map(u => `${u.id},${u.name}`).join('\n'); }
  hashPassword(pw) { /* crypto — yet another concern */ }
}

// AFTER — each class has exactly one reason to change
class UserRepository  { save(user)   { /* DB only */ } }
class EmailService    { send(to, msg){ /* SMTP only */ } }
class UserCsvExporter { export(users){ return users.map(u => `${u.id},${u.name}`).join('\n'); } }
class AuthUtils       { hashPassword(pw){ /* crypto only */ } }

// ══ O — Open/Closed: Strategy map ═════════════════════════════
// BEFORE — every new discount type requires editing calcPrice
function calcPriceBad(price, type) {
  if (type === 'student')  return price * 0.9;
  if (type === 'employee') return price * 0.75;
  // adding 'vip' means editing this function — OCP violation
  return price;
}

// AFTER — extend by adding to the map; calcPrice never changes
const discounts = {
  none:     ()      => 0,
  student:  (price) => price * 0.10,
  employee: (price) => price * 0.25,
};
function calcPrice(price, discountType) {
  const applyDiscount = discounts[discountType] ?? discounts.none;
  return price - applyDiscount(price);
}
// Adding VIP: one line, calcPrice untouched
discounts.vip = (price) => price * 0.30;
console.log(calcPrice(100, 'vip'));      // 70
console.log(calcPrice(100, 'student')); // 90
console.log(calcPrice(100, 'unknown')); // 100 (falls back to 'none')

// ══ D — Dependency Inversion: inject the gateway ══════════════
// BEFORE — tightly coupled to Stripe, cannot test without network
class OrderServiceBad {
  constructor() { this._gw = new StripeGateway(); } // ← hardcoded
  placeOrder(amount) { this._gw.charge(amount); }
}

// AFTER — accepts any object with a charge() method
class OrderService {
  constructor(paymentGateway) {  // ← abstraction injected
    this._gw = paymentGateway;
  }
  placeOrder(amount) {
    this._gw.charge(amount);
    console.log(`Order placed for $${amount}`);
  }
}

const stripe = { charge: (amt) => console.log(`Stripe charged $${amt}`) };
const paypal = { charge: (amt) => console.log(`PayPal charged $${amt}`) };
const fakeGw = { charge: jest => jest };  // test double

new OrderService(stripe).placeOrder(50);  // Stripe charged $50
new OrderService(paypal).placeOrder(50);  // PayPal charged $50

// ══ DRY: single source of truth ═══════════════════════════════
// BAD — validation logic duplicated in two places
function registerUser(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email');
  if (age < 18) throw new Error('Must be 18 or older');
  // ... register
}
function updateProfile(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email'); // copy-pasted!
  if (age < 18) throw new Error('Must be 18 or older');      // copy-pasted!
  // ... update
}
// When the min age changes to 16, you must find both copies.

// GOOD — one authoritative function
function validateUserInput(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email');
  if (age < 18) throw new Error('Must be 18 or older');
}
function registerUser2(email, age) {
  validateUserInput(email, age);
  console.log('Registering', email);
}
function updateProfile2(email, age) {
  validateUserInput(email, age);
  console.log('Updating profile for', email);
}

// ══ KISS: remove pointless complexity ════════════════════════
const isEven_bad = (n) => n % 2 === 0 ? true : false; // ternary adds nothing
const isEven     = (n) => n % 2 === 0;                 // the expression is the answer

// Composed small functions beat one large function
const formatCurrency = (n)         => `$${n.toFixed(2)}`;
const applyTax       = (n, rate)   => n * (1 + rate);
const sumItems       = (items)     => items.reduce((s, i) => s + i.price, 0);
const calcTotal      = (items, taxRate) =>
  formatCurrency(applyTax(sumItems(items), taxRate));

console.log(calcTotal([{ price: 9.99 }, { price: 4.99 }], 0.10)); // $16.48

// ══ YAGNI: no plugin system for one use case ═════════════════
// BAD — building infrastructure for imagined future requirements
class PluginRegistry {
  #plugins = new Map();
  register(name, plugin) { this.#plugins.set(name, plugin); }
  run(name, ...args)     { return this.#plugins.get(name)?.execute(...args); }
  listAll()              { return [...this.#plugins.keys()]; }
}
// 80 lines of infrastructure for a feature that has exactly one implementation

// GOOD — start with the direct solution
function processPayment(amount, currency = 'USD') {
  // direct implementation — add abstraction when the second gateway arrives
  console.log(`Charged ${currency} ${amount} via Stripe`);
}

// ══ Naming: verbs, predicates, nouns ══════════════════════════
// BAD names
const data    = fetchUser(1);       // 'data' tells you nothing
function check(u) {}                // check what? for what?
const flag = user.emailVerified;    // 'flag' is meaningless noise

// GOOD names
const user           = fetchUserById(1);  // noun, parameterised
function isEmailVerified(user) {}          // predicate form — clearly boolean
const hasVerifiedEmail = user.emailVerified; // predicate name for boolean

console.log('All examples complete — clean code in action.');
